INSERT INTO events (title, category, event_date, event_time, venue, organizer, description, status) VALUES
  ('CHARUSAT National Tech Fest & Hackathon 2026', 'Tech Fest', '2026-10-25', '09:00 AM - 06:00 PM', 'Central Auditorium & Computer Center', 'Department of Computer Engineering', 'Annual national-level 24-hour hackathon with tracks in Web Development, AI/ML, Cloud Computing, and Cybersecurity. Exciting cash prizes and internship offers.', 'open'),
  ('Mid-Semester Examination Schedule - Semester 3 & 4', 'Examination', '2026-10-28', '10:30 AM - 01:30 PM', 'FTE Examination Halls (Block A & B)', 'Office of Controller of Examinations', 'Official mid-term examination timetable for all B.Tech engineering branches. Students must carry valid university identity cards and exam admit slips.', 'closed'),
  ('Hands-on Workshop on Cloud Computing & Kubernetes', 'Workshop', '2026-11-02', '02:00 PM - 05:00 PM', 'Advanced Computing Lab (Lab 402)', 'Google Developer Student Club (GDSC)', 'Interactive technical workshop covering Docker containerization, Kubernetes cluster orchestration, and Google Cloud deployment workflows.', 'closed'),
  ('AI & Generative Deep Learning Bootcamp', 'Tech Fest', '2026-11-05', '10:00 AM - 04:30 PM', 'Seminar Hall 1, FTE Building', 'AI & Data Science Student Chapter', 'Deep dive into Large Language Models, Prompt Engineering, Retrieval-Augmented Generation (RAG), and building multimodal AI applications.', 'open'),
  ('Annual Inter-College Sports Meet - Spardha 2026', 'Sports', '2026-11-10', '08:00 AM - 05:00 PM', 'University Sports Complex & Grounds', 'CHARUSAT Sports Council', 'Annual university sports tournament featuring Cricket, Football, Volleyball, Basketball, Athletics, and indoor games. Trophies for winning college departments.', 'closed'),
  ('Campus Placement Drive & Internship Fair 2026', 'Career', '2026-11-15', '09:30 AM - 05:30 PM', 'Training & Placement Cell (T&P Cell)', 'University Industry Interaction Cell', 'Recruitment drive by leading IT companies and MNCs for software engineering, cloud architecture, QA engineering, and product analyst roles.', 'open'),
  ('Annual Cultural Festival - Vrund 2026', 'Cultural', '2026-11-20', '05:00 PM - 10:00 PM', 'University Open Air Theatre', 'Student Cultural Committee', 'Grand cultural evening celebrating music, drama, traditional dance performances, fashion walk, and live musical concert by renowned artists.', 'closed'),
  ('Cybersecurity & Ethical Hacking Hands-on Training', 'Workshop', '2026-11-24', '11:00 AM - 03:00 PM', 'Network Security Lab (Lab 205)', 'Department of Information Technology', 'Practical session on web application vulnerabilities (OWASP Top 10), penetration testing techniques, packet sniffing, and defensive security measures.', 'closed'),
  ('Web Development Frameworks Lab Practical Evaluation', 'Academic', '2026-11-28', '09:00 AM - 01:00 PM', 'Web Technology Lab (Lab 301)', 'Faculty of Technology & Engineering', 'Continuous evaluation and code walkthrough for semester laboratory practicals, covering semantic HTML5, CSS Grid/Flexbox, DOM, and Fetch API.', 'closed'),
  ('Alumni Mentorship & Higher Education Webinar', 'Career', '2026-12-02', '04:00 PM - 06:00 PM', 'Virtual Meet (Google Meet / YouTube Live)', 'CHARUSAT Alumni Association', 'Interactive panel discussion with alumni working at top global tech firms, sharing guidance on GRE/TOEFL preparation, MS admissions, and tech careers.', 'closed'),
  ('Cross-Platform Mobile App Development with Flutter', 'Workshop', '2026-12-06', '01:30 PM - 04:30 PM', 'Mobile Computing Lab (Lab 108)', 'ACM Student Chapter', 'Step-by-step masterclass on building responsive Android and iOS apps using Flutter and Dart, including REST API integration and state management.', 'open'),
  ('Final Year Capstone Project Innovation Fair', 'Academic', '2026-12-10', '10:00 AM - 04:00 PM', 'FTE Exhibition Gallery', 'Project Review Committee', 'Showcase of innovative multidisciplinary engineering prototypes and software solutions evaluated by industry experts and academic judges.', 'closed'),
  ('University Table Tennis & Badminton Championship', 'Sports', '2026-12-14', '02:00 PM - 07:00 PM', 'Indoor Sports Complex', 'Physical Education Department', 'Singles and doubles knockout tournament for undergraduate and postgraduate students. Certificates and medals for winners and runners-up.', 'closed'),
  ('End-Semester Examination Hall Ticket & Seating Plan', 'Examination', '2026-12-18', '09:00 AM - 12:00 PM', 'StudentHub Portal / Examination Cell', 'Office of the Registrar', 'Eligible students with minimum 80% attendance can generate and download digital examination hall tickets for university end-semester exams.', 'closed'),
  ('Open Source Contribution & Git/GitHub Masterclass', 'Workshop', '2026-12-22', '10:30 AM - 01:30 PM', 'Software Engineering Lab (Lab 202)', 'Open Source Club CHARUSAT', 'Hands-on guide to version control, branching strategies, creating pull requests, writing clean documentation, and participating in global open source events.', 'open'),
  ('IoT & Embedded Systems Robotics Showcase', 'Tech Fest', '2026-12-26', '11:00 AM - 05:00 PM', 'Robotics & Automation Laboratory', 'Robotics & Electronics Club', 'Line-follower robots, autonomous drones, smart agriculture IoT devices, and home automation systems demonstration by student engineering teams.', 'closed'),
  ('Annual Blood Donation & Community Health Camp', 'Social', '2026-12-29', '09:00 AM - 03:00 PM', 'Charusat Hospital & Health Center', 'National Service Scheme (NSS)', 'Voluntary blood donation camp organized in collaboration with Red Cross Society. Free general health checkup and donor certificate provided.', 'closed'),
  ('Student Startup & Innovation Pitch Competition', 'Career', '2027-01-05', '10:00 AM - 03:30 PM', 'University Innovation & Incubation Center (EDC)', 'Student Startup and Innovation Policy (SSIP)', 'Present early-stage startup ideas to angel investors and industry leaders. Seed funding grants and incubation mentorship available for winning teams.', 'open');
